#include "Core.hpp"
#include "ScopedPublicationSource.hpp"
#include <iostream>
using namespace udm;
int wmain(int argc,wchar_t** argv){if(argc!=2)return 2;auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json checks=Json::array();std::string error;const auto check=[&](bool ok,const char* label){checks.push_back({{"passed",ok},{"name",label}});};try{
 for(const std::string mode:{"wrong-path","single-use","unrelated-job","unwind"}){auto folder=root/wide(mode);Manager manager(folder/L"catalog");auto prefs=manager.state["Settings"];prefs["DownloadFolder"]=utf8((folder/L"files").wstring());prefs["CategoryFolders"]=false;manager.setSettings(prefs);fs::create_directories(folder/L"files");auto first=manager.add("https://example.invalid/a","","a.bin","Main queue",true);auto a=folder/L"source-a.bin",b=folder/L"source-b.bin";atomicText(a,"owned A",false);atomicText(b,"owned B",false);const auto hashA=fileHash(a),hashB=fileHash(b);
 if(mode=="unwind"){try{ScopedPublicationSource held(manager,first,a,PublicationSourcePin::openRead(a));throw std::runtime_error("Owned unwind");}catch(const std::exception&){}manager.publishFile(first,b,hashB);check(str(first->data,"Status")=="Complete"&&readText(first->target())=="owned B"&&readText(a)=="owned A","An abandoned handoff releases its context without poisoning the next publication");}
 else{ScopedPublicationSource held(manager,first,a,PublicationSourcePin::openRead(a));
  if(mode=="wrong-path"){bool rejected=false;try{manager.publishFile(first,b,hashB);}catch(...){rejected=true;}check(rejected&&!fs::exists(first->target())&&readText(a)=="owned A"&&readText(b)=="owned B","A scoped pin cannot bless a different staging path");manager.publishFile(first,a,hashA);check(readText(first->target())=="owned A"&&readText(b)=="owned B","A rejected wrong-path call does not consume the valid handoff");}
  else if(mode=="single-use"){manager.publishFile(first,a,hashA);const auto accepted=first->target();first->data["FileName"]="second.bin";first->data["Status"]="Paused";atomicText(a,"new unowned A",false);bool rejected=false;try{manager.publishFile(first,a,fileHash(a));}catch(...){rejected=true;}check(rejected&&!fs::exists(first->target())&&readText(a)=="new unowned A"&&readText(accepted)=="owned A","A consumed pin cannot be replayed to publish a replacement under a new destination");}
  else{auto second=manager.add("https://example.invalid/b","","b.bin","Main queue",true);manager.publishFile(second,b,hashB);manager.publishFile(first,a,hashA);check(readText(second->target())=="owned B"&&readText(first->target())=="owned A","An unrelated job cannot steal another job's scoped source");}
 }manager.stop();
 }}catch(const std::exception& e){error=e.what();}const bool passed=error.empty()&&std::all_of(checks.begin(),checks.end(),[](const Json& r){return yes(r,"passed");});atomicText(root/L"results.json",Json{{"passed",passed},{"error",error},{"checks",checks}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<(passed?"passed":"failed")<<"\n";return passed?0:1;}
